#!/usr/bin/env python3
"""Record the test simulator and report when things start and stop moving.

Usage:
  tools/sim/record SECONDS OUTDIR [--then "COMMAND"] [--region NAME=X0,Y0,X1,Y1 ...]
                                  [--fps 60] [--threshold 0.1] [--full-size]

It starts recording, runs --then (for example `tools/sim/tap "Continue"` or
`tools/sim/app launch`), keeps recording for SECONDS after --then finishes, then
splits the video into frames.
For the screen below the status bar and for each --region (in points) it reports when motion
first starts and when it last changes (settles), in seconds from the start of
the video and from the first change anywhere on screen.

Files in OUTDIR: video.mp4, frames/00001.png ..., motion.csv (per-frame change
per region, for anything the summary does not answer).

--fps        frames per second to analyse (timing is accurate to 1/fps)
--threshold  percent of a region's pixels that must change for a frame to count
             as moving (default 0.1)
--full-size  keep full-resolution frames (default: half size, faster)

Warns when Reduce Motion is on, because then most animations do not play.
"""

import argparse
import csv
import glob
import os
import shutil
import signal
import subprocess
import sys
import time

sys.dont_write_bytecode = True  # keep __pycache__ out of tools/sim
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import _simlib as sim  # noqa: E402

PIXEL_CHANGE_LEVELS = 12  # ignores video-encoding noise in still areas
STATUS_BAR_POINTS = 54  # the "screen" region starts below the clock, whose minute change is not motion


def warn_if_reduce_motion(udid):
    result = sim.run(["xcrun", "simctl", "spawn", udid, "defaults", "read", "com.apple.Accessibility",
                      "ReduceMotionEnabled"], check=False)
    if result.returncode == 0 and result.stdout.strip() == "1":
        print("WARNING: Reduce Motion is ON in this simulator, so most animations will not play")


def record_video(udid, video_path, seconds, then_command):
    log_path = video_path + ".log"
    with open(log_path, "w") as log:
        recorder = subprocess.Popen(["xcrun", "simctl", "io", udid, "recordVideo", "--codec=h264", "--force", video_path],
                                    stdout=log, stderr=subprocess.STDOUT)
    deadline = time.time() + 10
    while time.time() < deadline:
        with open(log_path) as log:
            if "Recording started" in log.read():
                break
        time.sleep(0.1)
    else:
        recorder.kill()
        sim.die(f"recording did not start within 10 seconds; see {log_path}")
    recording_started = time.time()

    trigger_seconds = time.time() - recording_started
    if then_command:
        print(f"running: {then_command}")
        result = subprocess.run(then_command, shell=True, cwd=sim.REPO, capture_output=True, text=True)
        output = (result.stdout + result.stderr).strip()
        if output:
            print("\n".join(f"    {line}" for line in output.splitlines()))
        if result.returncode != 0:
            # A failed trigger would otherwise read as "no motion", which looks like a real result.
            recorder.send_signal(signal.SIGINT)
            recorder.wait(timeout=30)
            sim.die(f"--then failed (exit {result.returncode}), so nothing was measured")
    trigger_window = (trigger_seconds, time.time() - recording_started)
    time.sleep(seconds)
    recorder.send_signal(signal.SIGINT)
    recorder.wait(timeout=30)
    if not os.path.exists(video_path) or os.path.getsize(video_path) == 0:
        sim.die(f"no video was written; see {log_path}")
    return trigger_window


def extract_frames(video_path, frames_dir, fps, full_size):
    if shutil.which("ffmpeg") is None:
        sim.die("ffmpeg is not installed: `brew install ffmpeg`")
    os.makedirs(frames_dir, exist_ok=True)
    # A reused OUTDIR still holds the last run's frames; ffmpeg only overwrites as many as it writes.
    for old_frame in glob.glob(os.path.join(frames_dir, "*.png")):
        os.remove(old_frame)
    # The simulator only writes a frame when the screen changes; resampling to a
    # fixed fps repeats frames so frame N always sits at N / fps seconds.
    video_filter = f"fps={fps}" if full_size else f"fps={fps},scale=iw/2:-1"
    sim.run(["ffmpeg", "-loglevel", "error", "-y", "-i", video_path, "-vf", video_filter,
             os.path.join(frames_dir, "%05d.png")])
    return sorted(glob.glob(os.path.join(frames_dir, "*.png")))


def parse_regions(specs, screen_width, screen_height):
    regions = [("screen", (0, STATUS_BAR_POINTS, screen_width, screen_height))]
    for spec in specs:
        name, _, box = spec.partition("=")
        if name == "screen":
            sim.die('"screen" is the built-in whole-screen region; give your --region another name')
        try:
            regions.append((name, tuple(float(part) for part in box.split(","))))
        except ValueError:
            sim.die(f"--region must look like NAME=X0,Y0,X1,Y1 (points), got {spec!r}")
    return regions


def percent_changed(now, before):
    """Share of pixels (0-100) whose colour changed by more than PIXEL_CHANGE_LEVELS between two frames.

    A share, not an average, so a small element moving on a big screen still counts.
    """
    mask = sim.difference_mask(now, before, PIXEL_CHANGE_LEVELS)
    return 100 * mask.histogram()[255] / (mask.width * mask.height)


def analyse(frame_paths, regions, frame_scale, fps, threshold, csv_path):
    """Return {region: [changed-frame indexes]} and write the per-frame table."""
    from PIL import Image

    changed = {name: [] for name, _ in regions}
    previous = None
    with open(csv_path, "w", newline="") as file:
        writer = csv.writer(file)
        writer.writerow(["frame", "seconds"] + [name for name, _ in regions])
        for index, path in enumerate(frame_paths):
            frame = Image.open(path).convert("RGB")
            if previous is not None:
                row = [index, f"{index / fps:.3f}"]
                for name, box in regions:
                    pixels = tuple(round(value * frame_scale) for value in box)
                    change = percent_changed(frame.crop(pixels), previous.crop(pixels))
                    row.append(f"{change:.3f}")
                    if change > threshold:
                        changed[name].append(index)
                writer.writerow(row)
            previous = frame
    return changed


def main():
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("seconds", type=float)
    parser.add_argument("outdir")
    parser.add_argument("--then", dest="then_command")
    parser.add_argument("--region", action="append", default=[], metavar="NAME=X0,Y0,X1,Y1")
    parser.add_argument("--fps", type=int, default=60)
    parser.add_argument("--threshold", type=float, default=0.1)
    parser.add_argument("--full-size", action="store_true")
    options = parser.parse_args()
    udid = sim.simulator_id()

    if sim.simulator_state(udid) != "Booted":
        sim.die("the test simulator is not running; start the app with `tools/sim/app launch`")
    sim.require_pillow()
    width_pt, height_pt = sim.screen_size_points(udid)
    regions = parse_regions(options.region, width_pt, height_pt)  # before recording, so a typo fails fast
    warn_if_reduce_motion(udid)

    outdir = os.path.abspath(options.outdir)
    os.makedirs(outdir, exist_ok=True)
    video_path = os.path.join(outdir, "video.mp4")
    trigger_window = record_video(udid, video_path, options.seconds, options.then_command)
    frame_paths = extract_frames(video_path, os.path.join(outdir, "frames"), options.fps, options.full_size)
    if len(frame_paths) < 2:
        sim.die("the video has fewer than 2 frames")

    from PIL import Image

    frame_scale = Image.open(frame_paths[0]).width / width_pt
    csv_path = os.path.join(outdir, "motion.csv")
    changed = analyse(frame_paths, regions, frame_scale, options.fps, options.threshold, csv_path)

    print(f"video: {video_path} ({len(frame_paths)} frames at {options.fps} fps, {frame_scale:g}x)")
    if options.then_command:
        print(f"  --then ran from about {trigger_window[0]:.2f}s to {trigger_window[1]:.2f}s into the video")
    first_frames = [frames[0] for frames in changed.values() if frames]
    first_anywhere = min(first_frames) if first_frames else None
    for name, _ in regions:
        frames = changed[name]
        if not frames:
            print(f"  {name:<14} no motion (under {options.threshold:g}% of pixels changing)")
